-- ==========================================
-- CLOUDFLARE D1 DATABASE SCHEMA & SETUP
-- ==========================================

CREATE TABLE IF NOT EXISTS districts (
    key TEXT PRIMARY KEY,
    name TEXT,
    total_centers INTEGER,
    total_farmers INTEGER
);

CREATE TABLE IF NOT EXISTS centers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    district_key TEXT,
    sr INTEGER,
    samiti TEXT,
    upkendra TEXT,
    total_farmers INTEGER
);

CREATE TABLE IF NOT EXISTS farmers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    district_key TEXT,
    center_sr INTEGER,
    samiti TEXT,
    upkendra TEXT,
    kramank TEXT,
    code TEXT,
    name TEXT,
    father TEXT,
    total_paddy TEXT,
    first_date TEXT,
    transactions INTEGER,
    search_text TEXT
);

CREATE INDEX IF NOT EXISTS idx_farmers_dist_center ON farmers(district_key, center_sr);
CREATE INDEX IF NOT EXISTS idx_farmers_dist_code ON farmers(district_key, code);
CREATE INDEX IF NOT EXISTS idx_farmers_code_global ON farmers(code);
CREATE INDEX IF NOT EXISTS idx_centers_dist ON centers(district_key);


